Basic Usage
```ts ignore
import { delay } from "@ende/async";
import { ProgressBar } from "@ende/cli/unstable-progress-bar";

const gen = async function* () {
  for (let i = 0; i < 100; ++i) {
    yield new Uint8Array(1000).fill(97);
    await delay(Math.random() * 200 | 0);
  }
}();
const writer = (await Ende.create("./_tmp/output.txt")).writable.getWriter();

const bar = new ProgressBar({ max: 100_000 });

for await (const buffer of gen) {
  bar.value += buffer.length;
  await writer.write(buffer);
}

await bar.stop();
await writer.close();
```

Custom Formatting
```ts ignore
import { delay } from "@ende/async";
import { ProgressBar } from "@ende/cli/unstable-progress-bar";

const bar = new ProgressBar({
  max: 100,
  formatter(formatter) {
    return `[${formatter.styledTime}] [${formatter.progressBar}] [${formatter.value}/${formatter.max} files]`;
  },
});

for (const x of Array(100)) {
  bar.value += 1;
  await delay(Math.random() * 500);
}

await bar.stop();

