Basic Usage
```ts ignore no-assert
import { ProgressBarStream } from "@ende/cli/unstable-progress-bar-stream";

const response = await fetch("https://example.com/");
const max = Number(response.headers.get("content-length"));
let readable = response.body
if (max) {
  readable = readable
    ?.pipeThrough(new ProgressBarStream({ max })) ?? null;
}
await readable?.pipeTo((await Ende.create("./_tmp/example.com.html")).writable);
```

